edits.new:
// Draw bubbles (only circles for stocks)
const bubbles = svg.selectAll("circle")
    .data(nodes)
    .join("circle")
    .attr("cx", d => d.x)
    .attr("cy", d => d.y)
    .attr("r", d => d.radius)
    .attr("fill", d => sectorColors[d.sector])
    .attr("stroke", "#333")
    .attr("stroke-width", 1)
    .attr("class", d => `bubble-${d.ticker}`)
    .attr("data-ticker", d => d.ticker)
    .on("click", function(event, d) {
        highlightStock(d.ticker);
    })
    .on("mouseover", function(event, d) {
        if (!d.isETF) showTooltip(event, d);
    })
    .on("mouseout", hideTooltip);

// Add labels inside bubbles
svg.selectAll("text")
    .data(nodes)
    .join("text")
    .attr("x", d => d.x)
    .attr("y", d => d.y)
    .attr("class", "bubble-label")
    .text(d => d.ticker)
    .on("mouseover", function(event, d) {
        if (!d.isETF) showTooltip(event, d);
    })
    .on("mouseout", hideTooltip);

edits.old:
function showTooltip(event, d) {
    const [x, y] = d3.pointer(event);
    tooltip.style("opacity", 1)
        .html(`
            <strong>${d.ticker}</strong><br/>
            ${d.name}<br/>
            Sector: ${d.sector}<br/>
            Market Cap: ${formatMarketCap(d.marketCap)}
        `)
        .style("left", (x + 10) + "px")
        .style("top", (y - 10) + "px");
}

edits.new:
function showTooltip(event, d) {
    const [x, y] = d3.pointer(event);
    tooltip.classed("visible", true)
        .html(`
            <strong>${d.ticker}</strong><br/>
            ${d.name}<br/>
            Sector: ${d.sector}<br/>
            Market Cap: ${formatMarketCap(d.marketCap)}
        `)
        .style("left", (x + 10) + "px")
        .style("top", (y - 10) + "px");
}

