function showTableTooltip(element, ticker, name, sector) {
    const rect = element.getBoundingClientRect();
    tooltip.style("opacity", 1)
        .html(`
            <strong>${ticker}</strong><br/>
            ${name}<br/>
            Sector: ${sector}
        `)
        .style("left", (rect.left + 10) + "px")
        .style("top", (rect.top - 10) + "px");
}

